.v6239-wc-progress i{display:block;height:100%;background:linear-gradient(90deg,#4d8c34,#8ee059,#d4dd68);box-shadow:0 0 11px #70d74777}
.v6239-wc-note{margin-top:9px;padding:8px 9px;border:1px solid #5b4b29;border-radius:10px;background:#171309;color:#c8ba8e;font-size:7.5px;line-height:1.45}
.v6239-wc-note b{color:#efd178}

.v6239-wc-open{
  width:100%;min-height:44px;margin-top:10px;border:2px solid #9a7a2e;border-radius:12px;
  background:linear-gradient(180deg,#487f26,#1f4f18);color:#f0f4c8;font-weight:1000;
  box-shadow:inset 0 1px #d9ff9444,0 0 18px #6ac34833
}
.v6239-wc-open.ready{animation:v6239OpenPulse 1.6s ease-in-out infinite}
@keyframes v6239OpenPulse{50%{filter:brightness(1.2);box-shadow:inset 0 1px #e7ffb066,0 0 25px #70db4755}}

.v6239-wc-section-title{
  display:flex;align-items:center;justify-content:space-between;gap:8px;margin:12px 1px 7px;
  color:#d7ba78;font:1000 11px/1 Georgia,serif
}
.v6239-wc-section-title small{color:#748475;font:900 6px/1 system-ui,sans-serif}
.v6239-wc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}
.v6239-wc-slot{
  position:relative;min-height:145px;padding:8px;border:2px solid #4b5844;border-radius:13px;
  background:linear-gradient(180deg,#151d15,#090e0a);text-align:center;overflow:hidden
}
.v6239-wc-slot.claimed{opacity:.48;filter:saturate(.55)}
.v6239-wc-slot.gold{border-color:#8c6c2e}.v6239-wc-slot.harz{border-color:#459246}
.v6239-wc-slot.material{border-color:#4f6f8b}.v6239-wc-slot.gear{border-color:#755c88}.v6239-wc-slot.seed{border-color:#577f43}
.v6239-wc-art{height:66px;display:grid;place-items:center;font-size:37px}
.v6239-wc-art img{width:64px!important;height:64px!important;object-fit:contain!important;display:block!important}
.v6239-wc-slot b{display:block;color:#eef0df;font-size:8.5px;line-height:1.18}
.v6239-wc-slot small{display:block;margin-top:3px;color:#8e9b8d;font-size:6px;line-height:1.25}
.v6239-wc-slot button{
  width:100%;min-height:30px;margin-top:7px;border:1px solid #67773d;border-radius:8px;background:#172313;color:#dcedc1;font-size:7px;font-weight:1000
}
.v6239-wc-slot button:disabled{opacity:.55}
.v6239-wc-all{
  width:100%;min-height:42px;margin-top:10px;border:2px solid #7f682d;border-radius:11px;
  background:linear-gradient(#6d5622,#34250f);color:#f1d993;font-weight:1000
}
.v6239-wc-preview{display:grid;gap:5px}
.v6239-wc-preview-row{
  display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:7px;align-items:center;
  padding:7px 8px;border:1px solid #344334;border-radius:10px;background:#0a100b
}
.v6239-wc-preview-row .ico{font-size:20px;text-align:center}
.v6239-wc-preview-row b{display:block;font-size:8px;color:#e7e9db}
.v6239-wc-preview-row small{display:block;margin-top:2px;font-size:6px;color:#7f8e81}
.v6239-wc-preview-row em{font-style:normal;color:#b7d98d;font-size:7px;font-weight:1000}
.v6239-wc-activity{
  margin-top:12px;padding:9px;border:1px solid #384c37;border-radius:12px;background:#09100a
}
.v6239-wc-activity h4{margin:0 0 7px;color:#d8bd7d;font:1000 10px Georgia,serif}
.v6239-wc-activity-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.v6239-wc-activity-grid div{padding:6px;border:1px solid #2e3e2f;border-radius:8px;background:#070b08;color:#9eaa9e;font-size:6.5px}
.v6239-wc-activity-grid b{color:#dfe7d8}
.v6239-wc-lock-msg{text-align:center;padding:18px 8px;color:#b7bdaf;font-size:9px;line-height:1.5}

