<style id="v7161-inventory-scroll-compositor-css">
/*
  Android/Samsung WebView stability:
  when the large inventory enters the viewport, nested momentum scrolling, per-card
  transforms/filters and animated pseudo-elements can promote many item tiles to
  separate compositor layers. Keep the same 3-column visual hierarchy, but render
  the inventory as ordinary document paint so the hero/equipment area above it is
  not evicted while kinetic scrolling.
*/
#character #v459PanelInventory,
#character #v459PanelInventory > .card.v533-inv-card,
#character #inventory,
#character #inventory .inventory-grid{
  contain:none!important;
  content-visibility:visible!important;
  transform:none!important;
  -webkit-transform:none!important;
  filter:none!important;
  -webkit-filter:none!important;
  will-change:auto!important;
  perspective:none!important;
  isolation:auto!important;
  backface-visibility:visible!important;
  -webkit-backface-visibility:visible!important;
}
